'use strict';
const $=id=>document.getElementById(id), items=[];let busy=false,stop=false,serial=0;
const size=n=>n<1024?n+' B':n<1048576?(n/1024).toFixed(1)+' KB':(n/1048576).toFixed(2)+' MB';
function status(t){$('status').textContent=t;}
function controls(){for(const e of $('settings').elements)e.disabled=busy; $('compress').disabled=busy||!items.length;$('cancel').hidden=!busy;$('cancel').disabled=false;$('clear').disabled=busy||!items.length;$('choose').disabled=busy;$('zip').disabled=busy||!items.some(i=>i.result);}
function button(label,fn){const b=document.createElement('button');b.textContent=label;b.onclick=fn;b.disabled=busy;return b;}
function draw(){const root=$('items');root.replaceChildren();$('count').textContent=items.length;
 if(!items.length){const e=document.createElement('div');e.className='empty';e.textContent='Add a photo to get started.';root.append(e);}
 for(const i of items){const row=document.createElement('div');row.className='item';const img=document.createElement('img');img.className='thumb';img.src=i.url;img.alt='';const body=document.createElement('div'),name=document.createElement('div'),meta=document.createElement('div'),actions=document.createElement('div');name.className='name';name.textContent=i.file.name;meta.className='meta';meta.textContent=i.message||size(i.file.size)+' · Ready';actions.className='actions';
 if(i.result){actions.append(button('Compare',()=>compare(i)),button('Download',()=>download(i.result,i.outputName)));}
 actions.append(button('Remove',()=>{URL.revokeObjectURL(i.url);if(i.outURL)URL.revokeObjectURL(i.outURL);items.splice(items.indexOf(i),1);draw();}));body.append(name,meta,actions);row.append(img,body);root.append(row);}
 const done=items.filter(i=>i.result),before=done.reduce((s,i)=>s+i.file.size,0),after=done.reduce((s,i)=>s+i.result.size,0);$('summary').hidden=!done.length;$('summary').textContent=`${done.length} completed · ${size(before)} → ${size(after)} · ${before>=after?'Saved '+size(before-after):'Increased by '+size(after-before)}`;controls();
}
async function add(files){if(busy)return;const errors=[];for(const f of files){if(items.length>=50){errors.push('Batch limit is 50 images.');break;}if(!/^image\/(jpeg|png|webp)$/.test(f.type)){errors.push(f.name+': use JPG, PNG or WebP.');continue;}if(f.size>25*1048576||f.size===0){errors.push(f.name+': must be between 1 byte and 25 MB.');continue;}if(items.reduce((s,i)=>s+i.file.size,0)+f.size>200*1048576){errors.push('Batch limit is 200 MB.');break;}items.push({id:++serial,file:f,url:URL.createObjectURL(f)});}draw();status(errors.join(' '));}
$('choose').onclick=()=>$('files').click();$('files').onchange=e=>{add([...e.target.files]);e.target.value='';};
for(const event of ['dragenter','dragover'])$('drop').addEventListener(event,e=>{e.preventDefault();$('drop').classList.add('drag');});
for(const event of ['dragleave','drop'])$('drop').addEventListener(event,e=>{e.preventDefault();$('drop').classList.remove('drag');});
$('drop').addEventListener('drop',e=>add([...e.dataTransfer.files]));document.addEventListener('paste',e=>{const fs=[...e.clipboardData.files];if(fs.length)add(fs);});
$('clear').onclick=()=>{for(const i of items){URL.revokeObjectURL(i.url);if(i.outURL)URL.revokeObjectURL(i.outURL);}items.length=0;draw();status('');};
$('quality').oninput=()=>{$('qvalue').textContent=$('quality').value+'%';};$('preset').onchange=()=>{$('quality').value={balanced:80,small:55,high:92}[$('preset').value];$('quality').oninput();};
$('theme').onclick=()=>{document.body.classList.toggle('dark');try{localStorage.setItem('krishu-dark',document.body.classList.contains('dark'));}catch{}};try{if(localStorage.getItem('krishu-dark')==='true')document.body.classList.add('dark');}catch{}
function compare(i){$('before').src=i.url;$('after').src=i.outURL;$('beforeLabel').textContent='Original · '+size(i.file.size);$('afterLabel').textContent='Result · '+size(i.result.size);$('preview').showModal();}$('close').onclick=()=>{$('preview').close();$('before').removeAttribute('src');$('after').removeAttribute('src');};
function download(blob,name){const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}
function encode(canvas,type,q){return new Promise((resolve,reject)=>canvas.toBlob(b=>b&&b.type===type?resolve(b):reject(Error('This browser cannot export the selected format.')),type,q));}
async function animated(file){const a=new Uint8Array(await file.arrayBuffer()),v=new DataView(a.buffer),str=(p,n)=>String.fromCharCode(...a.slice(p,p+n));if(file.type==='image/png'){for(let p=8;p+12<=a.length;){const n=v.getUint32(p);if(str(p+4,4)==='acTL')return true;p+=12+n;}}if(file.type==='image/webp'){for(let p=12;p+8<=a.length;){const n=v.getUint32(p+4,true);if(str(p,4)==='ANIM')return true;p+=8+n+(n%2);}}return false;}
async function compress(i,s){if(await animated(i.file))throw Error('Animated images are not supported; animation was left untouched.');const img=new Image();img.src=i.url;await img.decode();if(img.naturalWidth*img.naturalHeight>40000000)throw Error('Image exceeds the 40 megapixel safety limit.');
 let scale=Math.min(1,s.width? s.width/img.naturalWidth:1,s.height?s.height/img.naturalHeight:1),w=Math.max(1,Math.round(img.naturalWidth*scale)),h=Math.max(1,Math.round(img.naturalHeight*scale));const canvas=document.createElement('canvas');let blob,type=s.format==='auto'?i.file.type:s.format;
 try{for(let round=0;round<12;round++){canvas.width=w;canvas.height=h;const ctx=canvas.getContext('2d');if(!ctx)throw Error('Canvas is unavailable in this browser.');if(type==='image/jpeg'){ctx.fillStyle=s.background;ctx.fillRect(0,0,w,h);}ctx.drawImage(img,0,0,w,h);blob=await encode(canvas,type,s.quality);
 if(s.target&&blob.size>s.target&&type!=='image/png'){let lo=.05,hi=s.quality;let low=await encode(canvas,type,lo);if(low.size<=s.target){blob=low;for(let step=0;step<7;step++){const mid=(lo+hi)/2,b=await encode(canvas,type,mid);if(b.size<=s.target){blob=b;lo=mid;}else hi=mid;}}else blob=low;}
 if(!s.target||blob.size<=s.target||(w===1&&h===1)||round===11)break;const factor=Math.min(.85,Math.max(.1,Math.sqrt(s.target/blob.size)*.92));w=Math.max(1,Math.floor(w*factor));h=Math.max(1,Math.floor(h*factor));}
 // Retain originals only when no requested conversion/resize/target would be undone.
 let kept=false;if(s.keep&&blob.size>=i.file.size&&type===i.file.type&&w===img.naturalWidth&&h===img.naturalHeight&&(!s.target||i.file.size<=s.target)){blob=i.file;kept=true;}
 if(i.outURL)URL.revokeObjectURL(i.outURL);i.result=blob;i.outURL=URL.createObjectURL(blob);const ext={'image/jpeg':'jpg','image/png':'png','image/webp':'webp'}[blob.type];const stem=i.file.name.replace(/\.[^.]+$/,'').replace(/[<>:"/\\|?*\u0000-\u001f]/g,'_')||'image';i.outputName=`${stem}-${i.id}-compressed.${ext}`;
 i.message=`${size(i.file.size)} → ${size(blob.size)} · ${w} × ${h} · ${kept?'Original kept':(100*(1-blob.size/i.file.size)).toFixed(1)+'% smaller'}${s.target?(blob.size<=s.target?' · Target met':' · Target not reached'):''}`;
 }finally{canvas.width=canvas.height=1;img.src='';}}
$('settings').onsubmit=async e=>{e.preventDefault();if(busy||!items.length)return;const s={quality:Number($('quality').value)/100,format:$('format').value,width:Number($('width').value),height:Number($('height').value),target:Number($('target').value)*1024,background:$('background').value,keep:$('keep').checked};busy=true;stop=false;draw();let completed=0;for(const i of items){if(stop)break;status(`Processing ${++completed} of ${items.length}…`);i.message='Processing…';draw();await new Promise(r=>setTimeout(r,0));try{await compress(i,s);}catch(err){if(i.outURL)URL.revokeObjectURL(i.outURL);i.result=null;i.outURL=null;i.message=err.message||'Could not decode this image.';}draw();}busy=false;draw();status(stop?'Stopped. Completed images are ready to download.':'Finished. Compare your images before downloading.');};
$('cancel').onclick=()=>{stop=true;status('Stopping after the current image…');};
// Dependency-free ZIP writer: stored entries, UTF-8 names, standard CRC-32.
const crcTable=Uint32Array.from({length:256},(_,n)=>{for(let k=0;k<8;k++)n=n&1?0xedb88320^(n>>>1):n>>>1;return n>>>0;});
function crc32(a){let c=0xffffffff;for(const b of a)c=crcTable[(c^b)&255]^(c>>>8);return(c^0xffffffff)>>>0;}
async function zipBlob(entries){const chunks=[],central=[];let offset=0,centralSize=0;const enc=new TextEncoder();for(const i of entries){const data=new Uint8Array(await i.result.arrayBuffer()),name=enc.encode(i.outputName),crc=crc32(data);const h=new Uint8Array(30+name.length),v=new DataView(h.buffer);v.setUint32(0,0x04034b50,true);v.setUint16(4,20,true);v.setUint16(6,0x800,true);v.setUint16(12,33,true);v.setUint32(14,crc,true);v.setUint32(18,data.length,true);v.setUint32(22,data.length,true);v.setUint16(26,name.length,true);h.set(name,30);chunks.push(h,data);const c=new Uint8Array(46+name.length),cv=new DataView(c.buffer);cv.setUint32(0,0x02014b50,true);cv.setUint16(4,20,true);cv.setUint16(6,20,true);cv.setUint16(8,0x800,true);cv.setUint16(14,33,true);cv.setUint32(16,crc,true);cv.setUint32(20,data.length,true);cv.setUint32(24,data.length,true);cv.setUint16(28,name.length,true);cv.setUint32(42,offset,true);c.set(name,46);central.push(c);offset+=h.length+data.length;centralSize+=c.length;}
 const end=new Uint8Array(22),v=new DataView(end.buffer);v.setUint32(0,0x06054b50,true);v.setUint16(8,entries.length,true);v.setUint16(10,entries.length,true);v.setUint32(12,centralSize,true);v.setUint32(16,offset,true);return new Blob([...chunks,...central,end],{type:'application/zip'});}
$('zip').onclick=async()=>{if(busy)return;busy=true;controls();status('Preparing ZIP…');try{download(await zipBlob(items.filter(i=>i.result)),'krishu-compressed-images.zip');status('ZIP ready.');}catch{status('ZIP could not be created. Try individual downloads or a smaller batch.');}finally{busy=false;controls();}};
